import{_ as i,c as l,o as e,ag as t}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"疑難排解","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/troubleshooting.md","filePath":"zh-TW/guide/troubleshooting.md","lastUpdated":1794112334000}'),s={name:"zh-TW/guide/troubleshooting.md"};function o(r,a,n,h,p,c){return e(),l("div",null,[...a[0]||(a[0]=[t(`<h1 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to &quot;疑難排解&quot;">​</a></h1><h2 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h2><h3 id="應用程式無法啟動" tabindex="-1">應用程式無法啟動 <a class="header-anchor" href="#應用程式無法啟動" aria-label="Permalink to &quot;應用程式無法啟動&quot;">​</a></h3><p><strong>現象</strong>：Nicasa 啟動失敗或立刻當掉</p><p><strong>解決辦法</strong>：</p><ol><li>確認系統為 macOS 10.13 或更高版本</li><li>確認至少擁有 4GB 記憶體</li><li>重新啟動你的 Mac</li><li>從 Mac App Store 重新安裝 Nicasa</li><li>檢查是否有衝突的應用程式</li></ol><h3 id="截圖無法使用" tabindex="-1">截圖無法使用 <a class="header-anchor" href="#截圖無法使用" aria-label="Permalink to &quot;截圖無法使用&quot;">​</a></h3><p><strong>現象</strong>：截圖功能不運作</p><p><strong>解決辦法</strong>：</p><ol><li><strong>授予螢幕錄製權限</strong>： <ul><li>進入 系統設定 &gt; 隱私權與安全性 &gt; 螢幕錄製</li><li>勾選 Nicasa 旁邊的註記框</li><li>重新啟動 Nicasa</li></ul></li><li>確認沒有其他截圖工具正在執行</li><li>嘗試重新啟動你的 Mac</li></ol><h3 id="chrome-擴充功能無法使用" tabindex="-1">Chrome 擴充功能無法使用 <a class="header-anchor" href="#chrome-擴充功能無法使用" aria-label="Permalink to &quot;Chrome 擴充功能無法使用&quot;">​</a></h3><p><strong>現象</strong>：擴充功能不顯示或無法擷取圖片</p><p><strong>解決辦法</strong>：</p><ol><li>確認擴充功能已在 Chrome 中啟用</li><li>檢查 Chrome 版本是否相容</li><li>嘗試重新整理網頁</li><li>重新安裝擴充功能</li><li>清除瀏覽器快取與 Cookie</li></ol><h3 id="圖片無法載入" tabindex="-1">圖片無法載入 <a class="header-anchor" href="#圖片無法載入" aria-label="Permalink to &quot;圖片無法載入&quot;">​</a></h3><p><strong>現象</strong>：縮圖不顯示或圖片打不開</p><p><strong>解決辦法</strong>：</p><ol><li>檢查圖片檔案的存取權限</li><li>確認圖片檔案未損壞</li><li>確認格式受支援（JPEG、PNG、GIF、BMP、TIFF、WebP）</li><li>嘗試重新開啟該檔案夾</li><li>重新啟動 Nicasa</li></ol><h3 id="效能緩慢" tabindex="-1">效能緩慢 <a class="header-anchor" href="#效能緩慢" aria-label="Permalink to &quot;效能緩慢&quot;">​</a></h3><p><strong>現象</strong>：應用程式卡頓或縮圖載入很慢</p><p><strong>解決辦法</strong>：</p><ol><li>關閉其他佔用記憶體較多的應用程式</li><li>確保有充足的可用記憶體（建議 8GB）</li><li>在偏好設定中調小縮圖格狀尺寸</li><li>清理應用程式快取</li><li>重新啟動你的 Mac</li></ol><h3 id="ai-編輯器無法使用" tabindex="-1">AI 編輯器無法使用 <a class="header-anchor" href="#ai-編輯器無法使用" aria-label="Permalink to &quot;AI 編輯器無法使用&quot;">​</a></h3><p><strong>現象</strong>：AI 編輯工具無法使用或不運作</p><p><strong>解決辦法</strong>：</p><ol><li>確認網路連線穩定（部分功能需要連網）</li><li>檢查你的 Mac 是否滿足最低需求</li><li>重新啟動 Nicasa</li><li>更新到最新版本</li><li>如問題依舊，請聯絡支援</li></ol><h3 id="權限問題" tabindex="-1">權限問題 <a class="header-anchor" href="#權限問題" aria-label="Permalink to &quot;權限問題&quot;">​</a></h3><p><strong>現象</strong>：應用程式要求權限，或某些功能無法使用</p><p><strong>解決辦法</strong>：</p><ol><li><strong>螢幕錄製</strong>：系統設定 &gt; 隱私權與安全性 &gt; 螢幕錄製</li><li><strong>輔助使用</strong>：系統設定 &gt; 隱私權與安全性 &gt; 輔助使用（用於懸浮模式）</li><li><strong>檔案與檔案夾</strong>：系統設定 &gt; 隱私權與安全性 &gt; 檔案與檔案夾</li><li>授予權限後重新啟動 Nicasa</li></ol><h3 id="懸浮模式問題" tabindex="-1">懸浮模式問題 <a class="header-anchor" href="#懸浮模式問題" aria-label="Permalink to &quot;懸浮模式問題&quot;">​</a></h3><p><strong>現象</strong>：透明懸浮模式運作不正常</p><p><strong>解決辦法</strong>：</p><ol><li>在系統設定中授予輔助使用權限</li><li>確認沒有其他懸浮類工具正在執行</li><li>嘗試關閉再重新開啟懸浮模式</li><li>重新啟動 Nicasa</li></ol><h2 id="錯誤訊息" tabindex="-1">錯誤訊息 <a class="header-anchor" href="#錯誤訊息" aria-label="Permalink to &quot;錯誤訊息&quot;">​</a></h2><h3 id="「需要螢幕錄製權限」" tabindex="-1">「需要螢幕錄製權限」 <a class="header-anchor" href="#「需要螢幕錄製權限」" aria-label="Permalink to &quot;「需要螢幕錄製權限」&quot;">​</a></h3><p><strong>解決辦法</strong>：依上文「截圖無法使用」一節所述授予螢幕錄製權限。</p><h3 id="「無法載入圖片」" tabindex="-1">「無法載入圖片」 <a class="header-anchor" href="#「無法載入圖片」" aria-label="Permalink to &quot;「無法載入圖片」&quot;">​</a></h3><p><strong>可能原因</strong>：</p><ul><li>檔案已損壞</li><li>格式不受支援</li><li>檔案權限問題</li><li>檔案過大</li></ul><p><strong>解決辦法</strong>：</p><ol><li>嘗試用「預覽程式」開啟該檔案，確認它是否有效</li><li>轉換為受支援的格式</li><li>檢查檔案權限</li><li>確認為合理的檔案大小</li></ol><h3 id="「擴充功能沒有回應」" tabindex="-1">「擴充功能沒有回應」 <a class="header-anchor" href="#「擴充功能沒有回應」" aria-label="Permalink to &quot;「擴充功能沒有回應」&quot;">​</a></h3><p><strong>解決辦法</strong>：重新整理網頁後重試。如果反覆出現，請重新安裝擴充功能。</p><h2 id="尋求協助" tabindex="-1">尋求協助 <a class="header-anchor" href="#尋求協助" aria-label="Permalink to &quot;尋求協助&quot;">​</a></h2><p>如果問題依然存在：</p><ol><li>查閱本疑難排解指南</li><li>前往我們的<a href="/zh-TW/guide/faq.html">常見問題</a></li><li>在 <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub</a> 上提交 issue</li><li>請附上你的 macOS 版本、Nicasa 版本以及重現問題的詳細步驟</li></ol><h2 id="系統資訊" tabindex="-1">系統資訊 <a class="header-anchor" href="#系統資訊" aria-label="Permalink to &quot;系統資訊&quot;">​</a></h2><p>回報問題時，請提供：</p><ul><li>macOS 版本（蘋果選單 &gt; 關於這台 Mac）</li><li>Nicasa 版本（Nicasa &gt; 關於 Nicasa）</li><li>Mac 機型與晶片（Apple 晶片或 Intel）</li><li>重現問題的步驟</li><li>任何錯誤訊息</li></ul><p>這通常意味著圖片檔案已被移動或刪除。請嘗試重新開啟該檔案夾或選擇其他目錄。</p><h3 id="「不支援的格式」" tabindex="-1">「不支援的格式」 <a class="header-anchor" href="#「不支援的格式」" aria-label="Permalink to &quot;「不支援的格式」&quot;">​</a></h3><p>無法辨識該圖片格式。請查看<a href="/zh-TW/guide/usage.html">支援的格式</a>清單，或將圖片轉換為相容格式。</p><h3 id="「記憶體不足」" tabindex="-1">「記憶體不足」 <a class="header-anchor" href="#「記憶體不足」" aria-label="Permalink to &quot;「記憶體不足」&quot;">​</a></h3><p>系統可用記憶體不足。請關閉其他應用程式，或升級你的記憶體。</p><h2 id="進階疑難排解" tabindex="-1">進階疑難排解 <a class="header-anchor" href="#進階疑難排解" aria-label="Permalink to &quot;進階疑難排解&quot;">​</a></h2><h3 id="查看日誌" tabindex="-1">查看日誌 <a class="header-anchor" href="#查看日誌" aria-label="Permalink to &quot;查看日誌&quot;">​</a></h3><p>存取應用程式日誌：</p><ol><li>進入 輔助說明 &gt; 顯示日誌</li><li>或在以下位置尋找日誌： <ul><li>Windows：<code>%APPDATA%\\Nicasa\\logs</code></li><li>macOS：<code>~/Library/Application Support/Nicasa/logs</code></li><li>Linux：<code>~/.config/Nicasa/logs</code></li></ul></li></ol><h3 id="重設應用程式" tabindex="-1">重設應用程式 <a class="header-anchor" href="#重設應用程式" aria-label="Permalink to &quot;重設應用程式&quot;">​</a></h3><p>將所有設定回復為預設值：</p><ol><li>關閉 Nicasa</li><li>刪除應用程式資料檔案夾</li><li>重新啟動 Nicasa</li></ol><h3 id="命令列選項" tabindex="-1">命令列選項 <a class="header-anchor" href="#命令列選項" aria-label="Permalink to &quot;命令列選項&quot;">​</a></h3><p>面向進階使用者，Nicasa 支援命令列參數：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 啟用詳細日誌</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-settings</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 重設所有設定</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/folder</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 開啟指定檔案夾</span></span></code></pre></div><h2 id="取得更多協助" tabindex="-1">取得更多協助 <a class="header-anchor" href="#取得更多協助" aria-label="Permalink to &quot;取得更多協助&quot;">​</a></h2><p>如果這些辦法都沒能解決你的問題：</p><ol><li>查看我們的<a href="/zh-TW/guide/faq.html">常見問題</a></li><li>搜尋已有的 <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">issues</a></li><li>新增 issue，並附上： <ul><li>你的作業系統與版本</li><li>Nicasa 版本</li><li>重現問題的步驟</li><li>任何錯誤訊息或截圖</li></ul></li></ol>`,68)])])}const u=i(s,[["render",o]]);export{g as __pageData,u as default};
